#pragma once

#include <cmath>
#include <cstdio>
#include <functional>
#include <string>
#include <vector>

namespace llmrt_test {

struct TestCase {
  const char* name;
  std::function<void()> fn;
};

inline std::vector<TestCase>& registry() {
  static std::vector<TestCase> r;
  return r;
}

inline int& failure_count() {
  static int n = 0;
  return n;
}

inline void report_failure(const char* file, int line, const std::string& msg) {
  ++failure_count();
  std::fprintf(stderr, "    FAIL %s:%d: %s\n", file, line, msg.c_str());
}

struct Registrar {
  Registrar(const char* name, std::function<void()> fn) {
    registry().push_back({name, std::move(fn)});
  }
};

inline int run_all(const char* suite) {
  int failed_tests = 0;
  std::printf("running %zu test(s) in %s\n", registry().size(), suite);
  for (auto& t : registry()) {
    failure_count() = 0;
    std::printf("  [ RUN  ] %s\n", t.name);
    t.fn();
    if (failure_count() == 0) {
      std::printf("  [  OK  ] %s\n", t.name);
    } else {
      std::printf("  [ FAIL ] %s (%d check(s) failed)\n", t.name, failure_count());
      ++failed_tests;
    }
  }
  std::printf("%s: %zu test(s), %d failed\n", suite, registry().size(), failed_tests);
  return failed_tests == 0 ? 0 : 1;
}

}  // namespace llmrt_test

