{"content": "#include "llmrt/json.h"

#include <cctype>
#include <cerrno>
#include <cmath>
#include <cstdlib>
#include <fstream>
#include <sstream>

#include "llmrt/common.h"

namespace llmrt {
namespace json {

// ---------------------------------------------------------------------------
// Parser
// ---------------------------------------------------------------------------
namespace {

class Parser {
 public:
  explicit Parser(std::string_view text) : s_(text) {}

  Value parse_document() {
    skip_ws();
    Value v = parse_value();
    skip_ws();
    if (!eof()) fail("trailing characters after top-level value");
    return v;
  }

 private:
  std::string_view s_;
  size_t pos_ = 0;
  int line_ = 1;
  int col_ = 1;

  [[noreturn]] void fail(const std::string& msg) const {
    throw Error("json: " + msg + " at line " + std::to_string(line_) +
                ", column " + std::to_string(col_));
  }

  bool eof() const { return pos_ >= s_.size(); }
  char peek() const { return eof() ? '\0' : s_[pos_]; }

  char get() {
    const char c = s_[pos_++];
    if (c == '\n') {
      ++line_;
      col_ = 1;
    } else {
      ++col_;
    }
    return c;
  }

  void skip_ws() {
    while (!eof()) {
      const char c = peek();
      if (c == ' ' || c == '\t' || c == '\n' || c == '\r') {
        get();
      } else {
        break;
      }
    }
  }

  void expect(char c) {
    if (eof() || peek() != c) {
      fail(std::string("expected '") + c + "'");
    }
    get();
  }

  bool consume(char c) {
    if (!eof() && peek() == c) {
      get();
      return true;
    }
    return false;
  }

  void expect_literal(const char* lit) {
    for (const char* p = lit; *p; ++p) {
      if (eof() || get() != *p) fail(std::string("invalid literal, expected \"") + lit + "\"");
    }
  }

  Value parse_value() {
    if (eof()) fail("unexpected end of input");
    switch (peek()) {
      case '{': return parse_object();
      case '[': return parse_array();
      case '"': return Value::make_string(parse_string());
      case 't': expect_literal("true"); return Value::make_bool(true);
      case 'f': expect_literal("false"); return Value::make_bool(false);
      case 'n': expect_literal("null"); return Value::make_null();
      default: return parse_number();
    }
  }

  Value parse_object() {
    expect('{');
    Value::Object obj;
    skip_ws();
    if (consume('}')) return Value::make_object(std::move(obj));
    while (true) {
      skip_ws();
      if (peek() != '"') fail("expected object key string");
      std::string key = parse_string();
      skip_ws();
      expect(':');
      skip_ws();
      obj.emplace_back(std::move(key), parse_value());
      skip_ws();
      if (consume(',')) continue;
      if (consume('}')) break;
      fail("expected ',' or '}' in object");
    }
    return Value::make_object(std::move(obj));
  }

  Value parse_array() {
    expect('[');
    Value::Array arr;
    skip_ws();
    if (consume(']')) return Value::make_array(std::move(arr));
    while (true) {
      skip_ws();
      arr.push_back(parse_value());
      skip_ws();
      if (consume(',')) continue;
      if (consume(']')) break;
      fail("expected ',' or ']' in array");
    }
    return Value::make_array(std::move(arr));
  }

  std::string parse_string() {
    expect('"');
