void dump_impl(const Value& v, std::string& out, int indent, int depth) {
  switch (v.type()) {
    case Type::Null: out += "null"; break;
    case Type::Bool: out += v.as_bool() ? "true" : "false"; break;
    case Type::Number:
      if (v.is_integer()) {
