  // leave those bits zero and preserve the high 16 bits exactly.
  const float samples[] = {0.0f,  -0.0f, 1.0f,   -1.0f,  0.1f,    -0.1f,
                           3.14159f, 1e-30f, 1e30f, 65504.0f, -1e-30f};
  for (const float f : samples) {
