    push_unique(l.gate_proj);
    push_unique(l.up_proj);
    push_unique(l.down_proj);
  }
  return v;
}

size_t Qwen3Weights::unique_bytes() const {
  size_t total = 0;
  for (const TensorInfo* t : all_tensors()) total += t->nbytes();
  return total;
}

