```cpp
#include "llmrt/tensor.h"

#include <sstream>

namespace llmrt {

std::vector<int64_t> contiguous_strides(const std::vector<int64_t>& shape) {
  std::vector<int64_t> s(shape.size());
  int64_t acc = 1;
  for (size_t i = shape.size(); i-- > 0;) {
    s[i] = acc;
    acc *= shape[i];
  }
  return s;
}

Tensor Tensor::contiguous(void* data, DType dtype, DeviceKind device, std::vector<int64_t> shape) {
  Tensor t;
  t.data = data;
  t.offset = 0;
  t.dtype = dtype;
  t.device = device;
  t.shape = std::move(shape);
  t.strides = contiguous_strides(t.shape);
  return t;
}

int64_t Tensor::dim(int i) const {
  LLMRT_CHECK(i >= 0 && static_cast<size_t>(i) < shape.size(),
              "Tensor::dim: axis " + std::to_string(i) + " out of range for shape " + shape_string());
  return shape[static_cast<size_t>(i)];
}

size_t Tensor::numel() const {
  size_t n = 1;
  for (const int64_t d : shape) {
    LLMRT_CHECK(d >= 0, "Tensor::numel: negative dimension in " + shape_string());
    n *= static_cast<size_t>(d);
