{"content": "#include <cmath>
#include <cstdio>
#include <string>
#include <vector>

#include "llmrt/common.h"
#include "llmrt/ops.h"
#include "llmrt/safetensors.h"
#include "llmrt/tensor.h"

#include "golden.h"
#include "test_framework.h"

using namespace llmrt;

namespace {

// A Tensor is only ever a view, so binding one to a const buffer means casting
// away const. Safe here because the ops under test only read their inputs.
Tensor view_of(const std::vector<float>& v, std::vector<int64_t> shape) {
  return Tensor::contiguous(const_cast<float*>(v.data()), DType::F32, DeviceKind::CPU,
                            std::move(shape));
}

bool checkpoint_exists() {
  return std::ifstream(golden::default_model_dir() + "/model.safetensors").good();
}

bool throws(const std::function<void()>& fn) {
  try {
    fn();
  } catch (const Error&) {
    return true;
  }
  return false;
}

// Loads a weight vector from the checkpoint in f32.
std::vector<float> weight_of(const SafeTensors& st, const std::string& name) {
  return st.to_f32(name);
}

}  // namespace

// ---------------------------------------------------------------------------
// Golden comparison: the real bar
// ---------------------------------------------------------------------------

// input_layernorm: normalises over hidden_size = 1024.
LLMRT_TEST(rmsnorm_matches_golden_input_layernorm) {
  golden::Store g;
  if (!g.available() || !checkpoint_exists()) {
    std::printf("      (skipped: fixtures or checkpoint missing)\n");
    return;
  }
  const golden::Array* in = g.get("input_layernorm_in");
  const golden::Array* want = g.get("input_layernorm_out");
  CHECK_TRUE(in != nullptr && want != nullptr);
  CHECK_EQ(in->shape, want->shape);

  const SafeTensors st = SafeTensors::open(golden::default_model_dir() + "/model.safetensors");
  const std::vector<float> w = weight_of(st, "model.layers.0.input_layernorm.weight");
  CHECK_EQ(w.size(), size_t{1024});

  std::vector<float> in_copy(in->f32);
  std::vector<float> out(in->numel());
  cpu::rmsnorm(view_of(in_copy, in->shape), view_of(w, {1024}), view_of(out, in->shape), 1e-6f);

  const golden::Diff d = golden::compare(out.data(), want->f(), want->numel());
  CHECK_MSG(golden::within(d), "input_layernorm: " + golden::diff_string(d));
}

// QK-Norm: the SAME kernel, but normalising over head_dim = 128 while the input
// row is 2048 wide. This is the test that catches normalising over the wrong
// axis -- the mistake that makes Qwen3 output plausible-looking garbage.
LLMRT_TEST(rmsnorm_matches_golden_q_norm_over_head_dim) {
  golden::Store g;
  if (!g.available() || !checkpoint_exists()) return;
  const golden::Array* proj = g.get("q_proj_out");  // [1, 12, 2048]
  const golden::Array* want = g.get("q_norm_out");  // [1, 12, 16, 128]
  CHECK_TRUE(proj != nullptr && want != nullptr);

  const SafeTensors st = SafeTensors::open(golden::default_model_dir() + "/model.safetensors");
  const std::vector<float> w = weight_of(st, "model.layers.0.self_attn.q_norm.weight");
  CHECK_EQ(w.size(), size_t{128});

  std::vector<float> in_copy(proj->f32);
  std::vector<float> out(proj->numel());

  // [1, 12, 2048] -> [1, 12, 16, 128]: reshape is free (contiguous).
  Tensor x = view_of(in_copy, proj->shape).reshape({1, 12, 16, 128});
  Tensor y = view_of(out, {1, 12, 16, 128});
  cpu::rmsnorm(x, view_of(w, {128}), y, 1e-6f);

  const golden::Diff d = golden::compare(out.data(), want->f(), want->numel());
  CHECK_MSG(golden::within(d), "q_norm: " + golden::diff_string(d));
}

// Negative control: prove the test above can actually fail. Normalising the
// *same* data over 2048 instead of 128 must NOT reproduce the golden output.
LLMRT_TEST(rmsnorm_over_the_wrong_axis_does_not_match) {
  golden::Store g;
  if (!g.available() || !checkpoint_exists()) return;
  const golden::Array* proj = g.get("q_proj_out");
  const golden::Array* want = g.get("q_norm_out");
  CHECK_TRUE(proj != nullptr && want != nullptr);

  const SafeTensors st = SafeTensors::open(golden::default_model_dir() + "/model.safetensors");
  // A 2048-long weight is nonsense for QK-Norm; that is the point.
  std::vector<float> w(2048, 1.0f);
  std::vector<float> in_copy(proj->f32);
  std::vector<float> out(proj->numel());
  cpu::rmsnorm(view_of(in_copy, proj->shape), view_of(w, {2048}), view_of(out, proj->shape),
               1e-6f);

  const golden::Diff d = golden::compare(out.data(), want->f(), want->numel());
  CHECK_MSG(!golden::within(d) || d.cosine < 0.999,
            "normalising over 2048 unexpectedly matched the 128-wide golden; the "
            "q_norm test has no discriminating power: " + golden::diff_string(d));
}

LLMRT_TEST(rmsnorm_matches_golden_k_norm) {
  golden::Store g;
  if (!g.available() || !checkpoint_exists()) return;
  const golden::Array* proj = g.get("k_proj_out");  // [1, 12, 1024]
  const golden::Array* want = g.get("k_norm_out");  // [1, 12, 8, 128]
  CHECK_TRUE(proj != nullptr && want != nullptr);

  const SafeTensors st = SafeTensors::open(golden::default_model_dir() + "/model.safetensors");
  const std::vector<float> w = weight_of(st, "model.layers.0.self_attn.k_norm.weight");
  CHECK_EQ(w.size(), size_t{128});

  std::vector<float> in_copy(proj->f32);
  std::vector<float> out(proj->numel());
  cpu::rmsnorm(view_of(in_copy, proj->shape).reshape({1, 12, 8, 128}), view_of(w, {128}),
               view_of(out, {1, 12, 8, 128}), 1e-6f);

  const golden::Diff d = golden::compare(out.data(), want->f(), want->numel());
  CHECK_MSG(golden::within(d), "k_norm: " + golden::diff_string(d));
}

// ---------------------------------------------------------------------------
// Properties that hold regardless of the reference
// ---------------------------------------------------------------------------

LLMRT_TEST(rmsnorm_normalises_to_unit_rms_when_weight_is_ones) {
  // out_j = x_j / sqrt(mean(x^2) + eps)  =>  mean(out^2) = m / (m + eps) ~ 1
  std::vector<float> x(64), out(64), w(64, 1.0f);
  for (size_t i = 0; i < x.size(); ++i) x[i] = std::sin(static_cast<float>(i) * 1.7f) * 3.0f;

  cpu::rmsnorm(view_of(x, {1, 64}), view_of(w, {64}), view_of(out, {1, 64}), 1e-6f);

  double mean_sq = 0.0;
  for (const float v : out) mean_sq += static_cast<double>(v) * v;
  mean_sq /= static_cast<double>(out.size());
  CHECK_NEAR(mean_sq, 1.0, 1e-5);
}

LLMRT_TEST(rmsnorm_is_linear_in_the_weight) {
  std::vector<float> x(32), w1(32), w2(32), o1(32), o2(32);
  for (size_t i = 0; i < x.size(); ++i) {
    x[i] = static_cast<float>(i) - 16.0f;
    w1[i] = 0.5f + 0.01f * static_cast<float>(i);
    w2[i] = 2.0f * w1[i];
  }
  cpu::rmsnorm(view_of(x, {1, 32}), view_of(w1, {32}), view_of(o1, {1, 32}), 1e-6f);
  cpu::rmsnorm(view_of(x, {1, 32}), view_of(w2, {32}), view_of(o2, {1, 32}), 1e-6f);
  for (size_t i = 0; i < o1.size(); ++i) {
    CHECK_NEAR(o2[i], 2.0 * o1[i], 1e-6);
  }
}

LLMRT_TEST(rmsnorm_treats_leading_axes_as_independent_rows) {
  // Two rows with very different magnitudes must not influence each other.
  std::vector<float> x = {1.0f, 1.0f, 1.0f, 1.0f,      // row 0: rms 1
                          10.0f, 10.0f, 10.0f, 10.0f};  // row 1: rms 10
  std::vector<float> w(4, 1.0f), out(8);
  cpu::rmsnorm(view_of(x, {2, 4}), view_of(w, {4}), view_of(out, {2, 4}), 1e-6f);

  // Both rows normalise to ~1, proving row 1 saw only its own statistics.
  for (int r = 0; r < 2; ++r) {
    for (int j = 0; j < 4; ++j) {
      CHECK_NEAR(out[static_cast<size_t>(r * 4 + j)], 1.0, 1e-5);
    }
  }
}

LLMRT_TEST(rmsnorm_handles_rank_1_input) {
  std::vector<float> x = {3.0f, 4.0f};  // mean(x^2) = 12.5
  std::vector<float> w(2, 1.0f), out(2);
  cpu::rmsnorm(view_of(x, {2}), view_of(w, {2}), view_of(out, {2}), 1e-6f);
  const double scale = 1.0 / std::sqrt(12.5 + 1e-6);
  CHECK_NEAR(out[0], 3.0 * scale, 1e-6);
  CHECK_NEAR(out[1], 4.0 * scale, 1e-6);
}

// ---------------------------------------------------------------------------
// Argument validation: wrong input must fail loudly
// ---------------------------------------------------------------------------

LLMRT_TEST(rmsnorm_rejects_bad_arguments) {
  std::vector<float> x(8, 1.0f), out(8);
  const std::vector<int64_t> shape2d = {2, 4};

  // Weight length must equal the normalised axis.
  std::vector<float> short_w(3, 1.0f);
  CHECK_TRUE(throws([&] {
    cpu::rmsnorm(view_of(x, shape2d), view_of(short_w, {3}), view_of(out, shape2d), 1e-6f);
  }));

  // Output shape must match input.
  CHECK_TRUE(throws([&] {
    std::vector<float> w(4, 1.0f);
    cpu::rmsnorm(view_of(x, shape2d), view_of(w, {4}), view_of(out, {4, 2}), 1e-6f);
  }));

  // A transposed (strided) input must be refused, not silently misread.
  CHECK_TRUE(throws([&] {
    std::vector<float> w(4, 1.0f);
    Tensor strided = view_of(x, shape2d).transpose(0, 1);
    cpu::rmsnorm(strided, view_of(w, {4}), view_of(out, shape2d), 1e-6f);
  }));

  // Wrong dtype.
  CHECK_TRUE(throws([&] {
    std::vector<float> w(4, 1.0f);
    Tensor bf16 = Tensor::contiguous(x.data(), DType::BF16, DeviceKind::CPU, shape2d);
    cpu::rmsnorm(bf16, view_of(w, {4}), view_of(out, shape2d), 1e-6f);
  }));

  // eps must be positive.
  CHECK_TRUE(throws([&] {
    std::vector<float> w(4, 1.0f);
    cpu::rmsnorm(view_of(x, shape2d), view_of(w, {4}), view_of(out, shape2d), 0.0f);
  }));

  // Rank 0 has no axis to normalise over.
  CHECK_TRUE(throws([&] {
    std::vector<float> w(1, 1.0f), scalar(1);
    cpu::rmsnorm(view_of(scalar, {}), view_of(w, {1}), view_of(scalar, {}), 1e-6f);
  }));
}

int main() { return llmrt_test::run_all("ops_cpu"); }
