// kernels/rmsnorm.cl
//
// GPU counterpart of src/ops/cpu/rmsnorm.cpp.
//
// The CPU version scans each row twice and relies on the L1 cache to make the
// second scan free. A GPU has no such transparent cache across a work-group:
// if we wrote the same two loops here, both would go to global memory, and the
// kernel would be memory-bound on twice the necessary traffic.
//
// So instead we stage the row in __local memory once. The second pass then
// reads from __local at effectively L1 speed, and global memory is touched
// exactly once for the read and once for the write.

#define WG_SIZE 256

__kernel void rmsnorm(
    __global const float* x,      // [rows, n]
    __global const float* weight, // [n]
    __global float* out,          // [rows, n]
    const int n,
    const float eps)
{
    const int row = get_group_id(0);
    const int lid = get_local_id(0);       // 0..WG_SIZE-1
    const int lsize = get_local_size(0);

    // Each work-group owns one row. The row is staged here once.
    extern __shared__ float srow[];        // n floats
    extern __shared__ float ssum[];        // reduction scratch

    const __global float* xrow = x + (size_t)row * n;
    __global float* orow = out + (size_t)row * n;

    // --- stage the row into __local, accumulating squares on the way -------
    float local_sum = 0.0f;
    for (int j = lid; j < n; j += lsize) {
        const float v = xrow[j];           // the only global read of x
        srow[j] = v;
        local_sum += v * v;
    }

    // --- reduce the per-thread partial sums across the work-group ----------
    ssum[lid] = local_sum;
    barrier(CLK_LOCAL_MEM_FENCE);
    for (int stride = lsize / 2; stride > 0; stride >>= 1) {
        if (lid < stride) ssum[lid] += ssum[lid + stride];
        barrier(CLK_LOCAL_MEM_FENCE);
    }

    const float scale = 1.0f / sqrt(ssum[0] / (float)n + eps);
    barrier(CLK_LOCAL_MEM_FENCE);           // ssum[0] must be read before reuse

    // --- second pass, reading from __local --------------------------------
    for (int j = lid; j < n; j += lsize) {
        orow[j] = weight[j] * (srow[j] * scale);
    }
}
